// Discounted price in won, rounded to the nearest won.
export function applyDiscount(price, percent) {
  if (percent <= 0) return price
  return Math.round(price * (100 - percent) / 100)
}

folder.src/format.mjs:
import { applyDiscount } from './price.mjs'

export function formatWon(amount) {
  return `${amount.toLocaleString('en-US')}원`
}

export function priceLabel(price, percent) {
  return formatWon(applyDiscount(price, percent))
}

folder.test/price.test.mjs:
import test from 'node:test'
import assert from 'node:assert/strict'
import { applyDiscount } from '../src/price.mjs'
import { formatWon, priceLabel } from '../src/format.mjs'

test('no discount keeps the price', () => {
  assert.equal(applyDiscount(10000, 0), 10000)
})

test('10% off 10000 is 9000', () => {
  assert.equal(applyDiscount(10000, 10), 9000)
})

test('15% off 9990 is rounded to the nearest won', () => {
  assert.equal(applyDiscount(9990, 15), 8492)
})

test('formatWon groups thousands', () => {
  assert.equal(formatWon(1234567), '1,234,567원')
})

test('priceLabel shows the discounted price', () => {
  assert.equal(priceLabel(20000, 25), '15,000원')
})

